def solveD(I):
    H,W=len(I),len(I[0])
    cnt=collections.Counter(x for r in I for x in r); bg=max(cnt,key=cnt.get)
    O=[r[:] for r in I]
    # maximal straight diagonal runs (8-connected, collinear), per color
    used=set()
    for i in range(H):
        for j in range(W):
            if I[i][j]==bg or (i,j) in used: continue
            st=[(i,j)]; comp={(i,j)}; used.add((i,j)); col=I[i][j]; cur=[(i,j)]
            while st:
                rr,cc=st.pop()
                for dr,dc in [(-1,-1),(-1,1),(1,-1),(1,1)]:
                    nr,nc=rr+dr,cc+dc
                    if 0<=nr<H and 0<=nc<W and (nr,nc) not in used and I[nr][nc]==col:
                        used.add((nr,nc)); st.append((nr,nc)); comp.add((nr,nc)); cur.append((nr,nc))
            if len(cur)>=2:
                cs=sorted(cur)
                # determine common diagonal direction
                sgn_r=sign(cs[1][0]-cs[0][0]); sgn_c=sign(cs[1][1]-cs[0][1])
                d=(sgn_r,sgn_c)
                for start,end in [(cs[0],cs[-1]),(cs[-1],cs[0])]:
                    for step in [d,(-d[0],-d[1])]:
                        nr,nc=start[0]+step[0],start[1]+step[1]
                        while 0<=nr<H and 0<=nc<W and O[nr][nc]==bg:
                            O[nr][nc]=col; nr+=step[0]; nc+=step[1]
    return O
